function simpleFields(obj){if(!obj)return '';return `<dl class="morphology">${Object.entries(obj).filter(([k,v])=>!(k==='arthah'&&obj['अर्थः'])&&!['id','url','nishchayah','sutras','evidence','punardarshanam','token_ids','steps','sourceQuote','source_ranges','srotah','sources'].includes(k)&&v!=null&&v!=='').map(([k,v])=>{
 if(['sanjna_sutras','sanjna_sutra','vibhakti_sutras','vibhakti_sutra'].includes(k))return `<dt>${k.startsWith('sanjna')?'संज्ञासूत्रम्':'विभक्तिसूत्रम्'}</dt><dd>${rules(v)}</dd>`;
 if(k==='kriya_token_id'||k==='क्रिया'&&/^(?:BU|MK)\./.test(String(v)))return `<dt>सम्बद्धा क्रिया</dt><dd><button class="text-link" data-unit-jump="${esc(v)}">${esc(tokenLabel(v))} →</button></dd>`;
 if(k==='kriya_adhyahara')return `<dt>अध्याहृता क्रिया</dt><dd>${rich(text(v)||v)}</dd>`;
 if(!/[\u0900-\u097f]/.test(k)&&!label[k])return '';
 let val;if(k==='connected_to')val=`<button class="text-link" data-unit-jump="${esc(v)}">${esc(tokenLabel(v))} →</button>`;else if(k==='varttikas')val=list(v).map(r=>`<p>${link(r.url,r.text+' · '+r.source)} ${flag(r)}<span class="rule-note">${rich(r.note||'')}</span></p>`).join('');else if(Array.isArray(v))val=v.map(x=>rich(text(x)||x)).join(' · ');else if(typeof v==='object')val=v.url?link(v.url,v.label||v.text||v.root||v['धातुः']||'धातुः'):simpleFields(v)+rules(v.sutras)+(v.nishchayah?flag(v):'')+evidence(v);else if(k==='धातुः'&&obj.url)val=link(obj.url,v);else val=typeof v==='boolean'?(v?'आम्':'न'):rich(deva(v));
 return val?`<dt>${esc(label[k]||k)}</dt><dd>${val}</dd>`:'';
 }).join('')}</dl>`;}
function grammar(rows){return `<div class="unit-grammar">${list(rows).map(r=>`<article class="unit-note" id="${esc(r.id)}"><h3>${esc(r.padam||r.word||r.form)} ${flag(r)}</h3>${(r.previous_id||r.purvavat_ref||(typeof r.purvavat==='string'?r.purvavat:r.purvavat?.note_id))?`<p>पूर्ववत् · <button class="text-link" data-unit-jump="${esc(r.previous_id||r.purvavat_ref||(typeof r.purvavat==='string'?r.purvavat:r.purvavat?.note_id))}">पूर्वविवरणम्</button></p>`:''}<div class="grammar-level"><h4>रूपपरिचयः ${flag(r.starah1)}</h4>${simpleFields(r.starah1)}${evidence(r.starah1)}</div>${r.starah2?`<details class="grammar-level"><summary>प्रकृतिप्रत्ययविभागः ${flag(r.starah2)}</summary>${simpleFields(r.starah2)}${r.starah2.purvavat?`<button class="text-link" data-unit-jump="${esc(r.starah2.purvavat)}">पूर्ववत् · पूर्वविवरणम् →</button>`:''}${rules(r.starah2.sutras)}${evidence(r.starah2)}${list(r.starah2.punardarshanam).length?`<p>पुनर्दर्शनम् · ${list(r.starah2.punardarshanam).map(x=>`<button class="text-link" data-unit-jump="${esc(typeof x==='string'?x:x.id)}">सम्बद्धः पाठः</button>`).join(' · ')}</p>`:''}</details>`:''}${r.starah3?`<details class="grammar-level"><summary>प्रक्रिया ${flag(r.starah3)}</summary><p>${rich(r.starah3.reason||'')}</p>${r.starah3.presentation?arrowProcess(r.starah3.presentation):`<ol>${list(r.starah3.steps).map(s=>`<li><p>${rich(s.form||s.text||'')} ${flag(s)}</p>${s.explanation?`<p>${rich(s.explanation)}</p>`:''}${rules(s.sutras)}</li>`).join('')}</ol>`}${evidence(r.starah3)}</details>`:''}${evidence(r)}</article>`).join('')}</div>`;}
function sandhi(rows){return list(rows).map(r=>`<article class="unit-note" id="${esc(r.id)}"><h3>${rich(r.parts?.join(' + ')||r.pade||r.split||r.surface||'')} ${flag(r)}</h3><p>${esc(r.surface||r.result||'')} · ${esc(list(r.types||r.type||r.prakarah).join(' · '))}</p>${(r.explanation||r.note)?`<p>${rich(r.explanation||r.note)}</p>`:''}${r.previous_id?`<button class="text-link" data-unit-jump="${esc(r.previous_id||r.purvavat_ref||(typeof r.purvavat==='string'?r.purvavat:r.purvavat?.note_id))}">पूर्ववत् · पूर्वविवरणम्</button>`:''}${rules(r.sutras||r.steps?.flatMap(s=>s.sutras||[]))}${r.optional?`<p>वैकल्पिकम् · ${list(r.alternatives).map(x=>esc(text(x)||x)).join(' / ')}</p>`:''}${evidence(r)}</article>`).join('');}
