function glossary(rows){return list(rows).map(r=>`<article class="unit-note" id="${esc(r.id||'')}"><h3>${esc(r.padam||r.shabdah||r.word||'')} ${flag(r)}</h3><p>${rich(r.paryayah||r.meaning||r.definition||r.saralah_arthah||r.explanation||'')}</p>${r.source_label||r.source||typeof r.srotah==='string'?`<p class="subtle-note">स्रोतः · ${esc(r.source_label||r.source||r.srotah)}</p>`:''}${(r.quote||r.source_quote)?`<blockquote>${esc(r.quote||r.source_quote)}</blockquote>`:''}${r.lexicon_id?`<button class="text-link" data-unit-lexicon="${esc(r.lexicon_id)}">शब्दकोशे पठतु →</button>`:''}${evidence(r)}</article>`).join('');}
// Learner prose is a presentation of the stored analysis, never a replacement for it.
