function grammarComparisonLinks(id){return list(activeUnit?.grammar_comparisons).filter(r=>r.grammar_id===id).map(r=>` <a class="text-link grammar-comparison" href="#${esc(r.target_unit_id.replace(/^[A-Z]+\./u,''))}/${esc(r.target_grammar_id)}">तुलना · ${esc(r.target_word)} (${esc(deva(r.target_unit_id.replace(/^[A-Z]+\./u,'')))}) ↗</a>`).join('');}
